/* Pyxel Studio — an independent browser pixel editor. */
const $=id=>document.getElementById(id), art=$('art'),ctx=art.getContext('2d'),preview=$('preview'),pctx=preview.getContext('2d'),overlay=$('overlay'),octx=overlay.getContext('2d');
const palette=['#20252e','#384350','#586470','#8c929a','#bbc1bc','#e4dfcc','#f7edd6','#ffffff','#44334a','#644760','#935363','#c77976','#e8a18d','#efb56b','#f5d48b','#f6e7ae','#323d47','#3e6060','#55826d','#78a174','#a6ba86','#c9d3a0','#789ba0','#afd0c6','#343951','#4a5472','#657898','#8da6b7','#62577b','#91788f','#bd9da4','#dfc3be'];
let W=64,H=64,layers=[],selected=0,color='#efb56b',tool='pencil',zoom=8,history=[],future=[],drawing=false,start=null,last=null,strokeBase=null,dirty=false,saveTimer;
function makeLayer(name){return{name,visible:true,opacity:1,pixels:Array(W*H).fill(null)}}
function snapshot(){return JSON.stringify({width:W,height:H,layers,selected,name:$('name').value})}
function validate(s){return s&&Number.isInteger(s.width)&&Number.isInteger(s.height)&&s.width>=8&&s.width<=256&&s.height>=8&&s.height<=256&&Array.isArray(s.layers)&&s.layers.length>0&&s.layers.length<=32&&s.layers.every(l=>typeof l.name==='string'&&typeof l.visible==='boolean'&&Number.isFinite(l.opacity)&&l.opacity>=0&&l.opacity<=1&&Array.isArray(l.pixels)&&l.pixels.length===s.width*s.height&&l.pixels.every(c=>c===null||/^#[\da-f]{6}$/i.test(c)))}
function restore(s){if(typeof s==='string')s=JSON.parse(s);if(!validate(s))throw Error('Invalid project');W=s.width;H=s.height;layers=s.layers;selected=Math.max(0,Math.min(layers.length-1,s.selected||0));$('name').value=String(s.name||'untitled').slice(0,100);art.width=preview.width=W;art.height=preview.height=H;render();renderLayers();sizeCanvas()}
function remember(){history.push(snapshot());if(history.length>60)history.shift();future=[];buttons()}
function changed(){dirty=true;render();renderLayers();clearTimeout(saveTimer);saveTimer=setTimeout(autosave,350);buttons()}
function autosave(){try{localStorage.setItem('pyxel-studio-v1',snapshot());$('saved').textContent='● Autosaved';dirty=false}catch{$('saved').textContent='● Save project to keep it'}}
function buttons(){$('undo').disabled=!history.length;$('redo').disabled=!future.length}
function render(){ctx.clearRect(0,0,W,H);for(const l of layers){if(!l.visible)continue;ctx.globalAlpha=l.opacity;l.pixels.forEach((c,i)=>{if(c){ctx.fillStyle=c;ctx.fillRect(i%W,Math.floor(i/W),1,1)}})}ctx.globalAlpha=1;pctx.clearRect(0,0,W,H);pctx.drawImage(art,0,0);$('dimensions').textContent=`${W} × ${H}`;$('preview-size').textContent=`${W} × ${H} px`;$('tab-name').textContent=$('name').value||'untitled'}
function renderLayers(){const list=$('layers');list.replaceChildren();[...layers].reverse().forEach((l,j)=>{const i=layers.length-1-j,row=document.createElement('div');row.className='layer'+(i===selected?' selected':'');row.tabIndex=0;row.setAttribute('role','button');row.setAttribute('aria-label',`Select ${l.name}`);const eye=document.createElement('button');eye.textContent=l.visible?'◉':'○';eye.title=l.visible?'Hide layer':'Show layer';eye.onclick=e=>{e.stopPropagation();remember();l.visible=!l.visible;changed()};const thumb=document.createElement('canvas');thumb.width=W;thumb.height=H;thumb.className='layer-thumb';const tc=thumb.getContext('2d');l.pixels.forEach((c,n)=>{if(c){tc.fillStyle=c;tc.fillRect(n%W,Math.floor(n/W),1,1)}});const label=document.createElement('span');label.className='layer-name';label.textContent=l.name;const num=document.createElement('span');num.className='layer-number';num.textContent=String(i+1).padStart(2,'0');row.append(eye,thumb,label,num);row.onclick=()=>{selected=i;renderLayers()};row.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();selected=i;renderLayers()}};list.append(row)});$('opacity').value=Math.round(layers[selected].opacity*100);$('opacity-value').textContent=$('opacity').value+'%';$('delete-layer').disabled=layers.length===1;$('layer-up').disabled=selected===layers.length-1;$('layer-down').disabled=selected===0}
function sizeCanvas(){const width=W*zoom,height=H*zoom;$('canvas-wrap').style.width=width+'px';$('canvas-wrap').style.height=height+'px';overlay.width=width;overlay.height=height;$('zoom-label').textContent=Math.round(zoom*100)+'%';grid()}
function grid(){octx.clearRect(0,0,overlay.width,overlay.height);if(!$('grid').checked||zoom<4)return;octx.strokeStyle='#17202d50';octx.lineWidth=1;octx.beginPath();for(let x=0;x<=W;x++){octx.moveTo(x*zoom+.5,0);octx.lineTo(x*zoom+.5,H*zoom)}for(let y=0;y<=H;y++){octx.moveTo(0,y*zoom+.5);octx.lineTo(W*zoom,y*zoom+.5)}octx.stroke()}
function fit(){const area=$('canvas-area');zoom=Math.max(1,Math.min(16,Math.floor(Math.min((area.clientWidth-56)/W,(area.clientHeight-64)/H))));sizeCanvas()}
function setColor(c){if(!/^#[\da-f]{6}$/i.test(c))return;color=c.toLowerCase();$('color').value=$('custom').value=color;$('hex').value=color.toUpperCase();$('color-chip').style.background=color;document.querySelectorAll('#palette button').forEach(b=>b.classList.toggle('selected',b.dataset.color===color))}
const keys={pencil:'B',eraser:'E',fill:'G',picker:'I',line:'L',rect:'R'};
function setTool(t){tool=t;document.querySelectorAll('[data-tool]').forEach(b=>b.classList.toggle('active',b.dataset.tool===t));$('tool-key').textContent=keys[t];$('tool-label').textContent={pencil:'Pencil',eraser:'Eraser',fill:'Fill',picker:'Color picker',line:'Line',rect:'Rectangle'}[t]}
function point(e){const r=art.getBoundingClientRect();return{x:Math.floor((e.clientX-r.left)*W/r.width),y:Math.floor((e.clientY-r.top)*H/r.height)}}
function put(x,y,c){if(x>=0&&y>=0&&x<W&&y<H)layers[selected].pixels[y*W+x]=c}
function line(a,b,c){let x=a.x,y=a.y,dx=Math.abs(b.x-x),dy=-Math.abs(b.y-y),sx=x<b.x?1:-1,sy=y<b.y?1:-1,err=dx+dy;for(;;){put(x,y,c);if(x===b.x&&y===b.y)break;let e=2*err;if(e>=dy){err+=dy;x+=sx}if(e<=dx){err+=dx;y+=sy}}}
function flood(p,c){const arr=layers[selected].pixels,target=arr[p.y*W+p.x];if(target===c)return;const stack=[p.y*W+p.x];while(stack.length){const n=stack.pop();if(arr[n]!==target)continue;arr[n]=c;const x=n%W,y=Math.floor(n/W);if(x>0)stack.push(n-1);if(x<W-1)stack.push(n+1);if(y>0)stack.push(n-W);if(y<H-1)stack.push(n+W)}}
let eraseStroke=false;
art.oncontextmenu=e=>e.preventDefault();
art.onpointerdown=e=>{if(e.button!==0&&e.button!==2)return;e.preventDefault();const p=point(e);if(p.x<0||p.y<0||p.x>=W||p.y>=H)return;if(tool==='picker'&&e.button!==2){const d=ctx.getImageData(p.x,p.y,1,1).data;if(d[3])setColor('#'+[...d].slice(0,3).map(n=>n.toString(16).padStart(2,'0')).join(''));return}if(!layers[selected].visible){toast('Show this layer before drawing.');return}remember();eraseStroke=e.button===2||tool==='eraser';start=last=p;strokeBase=layers[selected].pixels.slice();drawing=true;art.setPointerCapture(e.pointerId);if(tool==='fill'&&!eraseStroke){flood(p,color);drawing=false;changed();return}put(p.x,p.y,eraseStroke?null:color);render()};
art.onpointermove=e=>{const p=point(e);$('coords').textContent=`x: ${p.x}   y: ${p.y}`;if(!drawing)return;p.x=Math.max(0,Math.min(W-1,p.x));p.y=Math.max(0,Math.min(H-1,p.y));const c=eraseStroke?null:color;if((tool==='line'||tool==='rect')&&!eraseStroke){layers[selected].pixels=strokeBase.slice();if(tool==='line')line(start,p,c);else{line(start,{x:p.x,y:start.y},c);line({x:p.x,y:start.y},p,c);line(p,{x:start.x,y:p.y},c);line({x:start.x,y:p.y},start,c)}}else line(last,p,c);last=p;render()};
function endStroke(){if(drawing){drawing=false;changed()}}art.onpointerup=endStroke;art.onpointercancel=endStroke;art.onlostpointercapture=endStroke;
function toast(s){$('toast').textContent=s;$('toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').classList.remove('show'),2800)}
function download(blob,name){const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function filename(){return ($('name').value.trim()||'untitled').replace(/[^\w .-]/g,'_')}
$('save').onclick=()=>{download(new Blob([JSON.stringify({format:'pxweb',version:1,...JSON.parse(snapshot())})],{type:'application/json'}),filename()+'.pxweb');autosave();toast('Project saved. Every pixel included.')};
$('export').onclick=()=>art.toBlob(b=>{if(b){download(b,filename()+'.png');toast('PNG exported at original pixel size.')}},'image/png');
$('undo').onclick=()=>{if(!history.length)return;future.push(snapshot());restore(history.pop());autosave();buttons()};$('redo').onclick=()=>{if(!future.length)return;history.push(snapshot());restore(future.pop());autosave();buttons()};
document.querySelectorAll('[data-tool]').forEach(b=>b.onclick=()=>setTool(b.dataset.tool));
palette.forEach(c=>{const b=document.createElement('button');b.style.background=c;b.dataset.color=c;b.title=c;b.setAttribute('aria-label','Choose '+c);b.onclick=()=>setColor(c);$('palette').append(b)});
$('color').oninput=$('custom').oninput=e=>setColor(e.target.value);$('hex').onchange=e=>{if(/^#[\da-f]{6}$/i.test(e.target.value))setColor(e.target.value);else{e.target.value=color.toUpperCase();toast('Use a hex color such as #EFB56B.')}};
$('grid').onchange=grid;$('zoom-in').onclick=()=>{zoom=Math.min(24,zoom+1);sizeCanvas()};$('zoom-out').onclick=()=>{zoom=Math.max(1,zoom-1);sizeCanvas()};$('fit').onclick=fit;
$('add-layer').onclick=()=>{if(layers.length>=32)return toast('Maximum 32 layers.');remember();layers.push(makeLayer('Layer '+(layers.length+1)));selected=layers.length-1;changed()};
$('delete-layer').onclick=()=>{if(layers.length<2)return;remember();layers.splice(selected,1);selected=Math.max(0,selected-1);changed()};
function moveLayer(d){const i=selected+d;if(i<0||i>=layers.length)return;remember();[layers[i],layers[selected]]=[layers[selected],layers[i]];selected=i;changed()}
$('layer-up').onclick=()=>moveLayer(1);$('layer-down').onclick=()=>moveLayer(-1);$('rename-layer').onclick=()=>{const n=prompt('Layer name',layers[selected].name);if(n&&n.trim()){remember();layers[selected].name=n.trim().slice(0,60);changed()}};
$('opacity').onpointerdown=()=>remember();$('opacity').onkeydown=e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key))remember()};$('opacity').oninput=e=>{layers[selected].opacity=Number(e.target.value)/100;$('opacity-value').textContent=e.target.value+'%';render();clearTimeout(saveTimer);saveTimer=setTimeout(autosave,350)};
$('name').oninput=()=>{render();clearTimeout(saveTimer);saveTimer=setTimeout(autosave,350)};
$('new').onclick=()=>$('new-dialog').showModal();$('new-dialog').addEventListener('close',()=>{if($('new-dialog').returnValue!=='create')return;const w=Number($('width').value),h=Number($('height').value);if(!Number.isInteger(w)||!Number.isInteger(h)||w<8||h<8||w>256||h>256)return;remember();W=w;H=h;layers=[makeLayer('Layer 1')];selected=0;$('name').value=$('new-name').value||'untitled';art.width=preview.width=W;art.height=preview.height=H;changed();fit();toast('A fresh canvas. Make it yours.')});
$('open').onclick=()=>$('file').click();$('file').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>16*1024*1024)throw Error('File too large');if(f.type.startsWith('image/')){const img=await createImageBitmap(f);if(img.width<8||img.height<8||img.width>256||img.height>256){img.close();throw Error('Use an image between 8 and 256 pixels on each side')}remember();W=img.width;H=img.height;art.width=preview.width=W;art.height=preview.height=H;ctx.drawImage(img,0,0);img.close();const d=ctx.getImageData(0,0,W,H).data;layers=[makeLayer('Imported image')];selected=0;for(let i=0;i<W*H;i++)if(d[i*4+3])layers[0].pixels[i]='#'+[d[i*4],d[i*4+1],d[i*4+2]].map(n=>n.toString(16).padStart(2,'0')).join('');$('name').value=f.name.replace(/\.[^.]+$/,'');changed()}else{const s=JSON.parse(await f.text());if(!validate(s))throw Error('This is not a valid .pxweb project');remember();restore(s);changed()}fit();toast('Project opened. Welcome back.')}catch(err){toast(err.message||'Could not open that file.')}finally{e.target.value=''}};
$('help').onclick=()=>$('help-dialog').showModal();document.onkeydown=e=>{if(['INPUT','TEXTAREA'].includes(document.activeElement.tagName)||document.querySelector('dialog[open]'))return;const k=e.key.toLowerCase();if(e.ctrlKey||e.metaKey){if(k==='z'){e.preventDefault();$(e.shiftKey?'redo':'undo').click()}if(k==='s'){e.preventDefault();$('save').click()}return}const t=Object.keys(keys).find(t=>keys[t].toLowerCase()===k);if(t)setTool(t)};
function demo(){layers=[makeLayer('Evening sky'),makeLayer('Island & cabin'),makeLayer('Little details')];selected=0;function rect(x,y,w,h,c){for(let yy=y;yy<y+h;yy++)for(let xx=x;xx<x+w;xx++)put(xx,yy,c)}for(let y=0;y<H;y++)rect(0,y,W,1,y<28?'#384350':y<35?'#4a5472':y<39?'#657898':'#3e6060');rect(43,9,8,8,'#efb56b');rect(41,11,12,4,'#efb56b');rect(43,17,8,1,'#c77976');rect(8,13,12,2,'#586470');rect(6,15,21,2,'#586470');rect(28,23,14,2,'#586470');rect(25,25,22,2,'#586470');selected=1;for(let y=37;y<52;y++){const half=Math.floor((y<43?(y-34)*2:(54-y)*2));rect(32-half,y,half*2,1,y<43?'#78a174':y<47?'#55826d':'#323d47')}rect(22,30,20,12,'#af8867');rect(24,32,16,9,'#c9ac80');for(let y=22;y<32;y++){let half=y-21;rect(32-half,y,half*2,1,'#935363');rect(31-half,y,2,1,'#c77976')}rect(38,22,3,6,'#586470');rect(28,34,5,8,'#44334a');rect(35,33,4,4,'#f5d48b');rect(24,33,2,4,'#efb56b');rect(23,42,21,2,'#8c929a');rect(29,44,3,3,'#bbc1bc');rect(26,47,4,2,'#bbc1bc');rect(16,34,2,9,'#62577b');for(let y=21;y<37;y++){const half=Math.floor((y-19)/3);rect(17-half,y,half*2+1,1,y%4===0?'#78a174':'#55826d')}rect(47,36,2,6,'#62577b');for(let y=26;y<38;y++){const half=Math.floor((y-24)/3);rect(48-half,y,half*2+1,1,y%4===0?'#78a174':'#55826d')}selected=2;[[9,8],[25,6],[35,13],[55,23],[15,24],[57,7],[5,29]].forEach(([x,y])=>put(x,y,'#bbc1bc'));[[7,46,7],[45,48,10],[16,56,14],[38,59,9],[3,61,5],[53,55,7]].forEach(([x,y,w])=>rect(x,y,w,1,'#55826d'));rect(32,53,9,1,'#789ba0');rect(35,55,4,1,'#789ba0');[[20,41],[41,41],[19,43],[44,43]].forEach(([x,y])=>put(x,y,'#f5d48b'));selected=1;render();renderLayers()}
try{const saved=localStorage.getItem('pyxel-studio-v1');if(saved)restore(saved);else demo()}catch{demo()}setColor(color);buttons();requestAnimationFrame(fit);let resizeTimer;window.addEventListener('resize',()=>{clearTimeout(resizeTimer);resizeTimer=setTimeout(fit,150)});
